package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type AmtRec struct { // 01 AMT-REC, 11 bytes
	ArAcct string // PIC X(4) @0 len=4
	ArAmt  decimal.Decimal // PIC 9(5)V99 @4 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsBigTotal decimal.Decimal // PIC 9(7)V99 len=9 = 0
var WsWrapTotal decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsSafeTotal decimal.Decimal // PIC 9(5)V99 len=7 = 0
var WsOverflows int64 // PIC 99 len=2 = 0
var WsCount int64 // PIC 99 len=2 = 0
var WsHalf decimal.Decimal // PIC 9(5)V9 len=6 = 0
var WsAmtEd string // PIC ZZ,ZZ9.99 len=9
var WsWrapEd string // PIC ZZ,ZZ9.99 len=9
var WsSafeEd string // PIC ZZ,ZZ9.99 len=9
var WsHalfEd string // PIC ZZ,ZZ9.9 len=8

var curRec AmtRec

var inputLines []string
var inputIdx int
var inputAtEnd bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func storePic97V99(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	scaled := t.Shift(2).IntPart()
	const mod int64 = 1000000000 // 10^7 * 100
	r := scaled % mod
	// COBOL unsigned; keep sign handling truncate toward zero
	return decimal.New(r, -2)
}

func storePic95V99(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(2)
	scaled := t.Shift(2).IntPart()
	const mod int64 = 10000000 // 10^5 * 100
	r := scaled % mod
	return decimal.New(r, -2)
}

func storePic95V9(d decimal.Decimal) decimal.Decimal {
	t := d.Truncate(1)
	scaled := t.Shift(1).IntPart()
	const mod int64 = 1000000 // 10^5 * 10
	r := scaled % mod
	return decimal.New(r, -1)
}

func addPic99(v int64, inc int64) int64 {
	t := v + inc
	// truncate toward zero already integer; keep low 2 digits
	r := t % 100
	if r < 0 {
		r = -r
		// for negative, COBOL unsigned not expected; keep positive mod
	}
	return r
}

func fitsPic95V99(d decimal.Decimal) bool {
	t := d.Truncate(2)
	// fits if 0 <= t <= 99999.99 (unsigned)
	if t.IsNegative() {
		return false
	}
	limit := decimal.New(9999999, -2) // 99999.99
	return t.Cmp(limit) <= 0
}

func formatZZZZ9dec(v decimal.Decimal, decDigits int) string {
	var scale int32
	if decDigits == 2 {
		scale = 2
	} else {
		scale = 1
	}
	t := v.Truncate(scale)
	if t.IsNegative() {
		t = t.Neg()
	}
	scaled := t.Shift(scale).IntPart()
	pow10 := int64(1)
	for i := 0; i < decDigits; i++ {
		pow10 *= 10
	}
	frac := scaled % pow10
	intPart := scaled / pow10
	// drop high-order digits beyond 5
	intPart = intPart % 100000
	digits := [5]int64{}
	tmp := intPart
	for i := 4; i >= 0; i-- {
		digits[i] = tmp % 10
		tmp /= 10
	}
	// integer display chars: Z Z , Z Z 9
	// positions: 0:Z(d0) 1:Z(d1) 2:',' 3:Z(d2) 4:Z(d3) 5:9(d4)
	var sb strings.Builder
	seen := false
	// d0
	if digits[0] != 0 {
		seen = true
		fmt.Fprintf(&sb, "%d", digits[0])
	} else {
		// Z with leading zero -> space (if seen, would be '0' but seen false here)
		sb.WriteByte(' ')
	}
	// d1
	if digits[1] != 0 {
		seen = true
		fmt.Fprintf(&sb, "%d", digits[1])
	} else {
		if seen {
			sb.WriteByte('0')
		} else {
			sb.WriteByte(' ')
		}
	}
	// comma
	if seen {
		sb.WriteByte(',')
	} else {
		sb.WriteByte(' ')
	}
	// d2
	if digits[2] != 0 {
		seen = true
		fmt.Fprintf(&sb, "%d", digits[2])
	} else {
		if seen {
			sb.WriteByte('0')
		} else {
			sb.WriteByte(' ')
		}
	}
	// d3
	if digits[3] != 0 {
		seen = true
		fmt.Fprintf(&sb, "%d", digits[3])
	} else {
		if seen {
			sb.WriteByte('0')
		} else {
			sb.WriteByte(' ')
		}
	}
	// d4 (9)
	fmt.Fprintf(&sb, "%d", digits[4])
	sb.WriteByte('.')
	// fraction zero-padded
	s := fmt.Sprintf("%0*d", decDigits, frac)
	sb.WriteString(s)
	return sb.String()
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseAmtField(s string) decimal.Decimal {
	// s length 7, digits only, implied V99
	var cents int64 = 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		var d int64 = 0
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		cents = cents*10 + d
	}
	return decimal.New(cents, -2)
}

func formatPic99(v int64) string {
	v = v % 100
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%02d", v)
}

func MAINPARA() {
	// OPEN INPUT AMT-FILE
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	// split preserving spaces
	raw := strings.Split(string(data), "\n")
	inputLines = nil
	for i, ln := range raw {
		if i == len(raw)-1 && ln == "" {
			break
		}
		if strings.HasSuffix(ln, "\r") {
			ln = ln[:len(ln)-1]
		}
		inputLines = append(inputLines, ln)
	}
	inputIdx = 0
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	// CLOSE AMT-FILE (nothing)
	SUMMARYPARA()
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 11 {
		line = line + strings.Repeat(" ", 11-len(line))
	} else if len(line) > 11 {
		line = line[:11]
	}
	acct := line[0:4]
	amtStr := line[4:11]
	curRec.ArAcct = acct
	curRec.ArAmt = parseAmtField(amtStr)
}

func PROCESSPARA() {
	// ADD AR-AMT TO WS-BIG-TOTAL
	WsBigTotal = storePic97V99(WsBigTotal.Add(curRec.ArAmt))
	// MOVE WS-BIG-TOTAL TO WS-WRAP-TOTAL
	WsWrapTotal = storePic95V99(WsBigTotal)
	// ADD AR-AMT TO WS-SAFE-TOTAL ON SIZE ERROR PERFORM OVERFLOW-PARA
	candidate := WsSafeTotal.Add(curRec.ArAmt).Truncate(2)
	if fitsPic95V99(candidate) {
		WsSafeTotal = storePic95V99(candidate)
	} else {
		OVERFLOWPARA()
	}
	// ADD 1 TO WS-COUNT
	WsCount = addPic99(WsCount, 1)
	// COMPUTE WS-HALF = AR-AMT / 2 (truncated)
	halfExact := curRec.ArAmt.Mul(decimal.NewFromInt(5)).Shift(-1)
	WsHalf = storePic95V9(halfExact)
	// MOVEs to edited
	WsAmtEd = formatZZZZ9dec(curRec.ArAmt, 2)
	WsWrapEd = formatZZZZ9dec(WsWrapTotal, 2)
	WsSafeEd = formatZZZZ9dec(WsSafeTotal, 2)
	WsHalfEd = formatZZZZ9dec(WsHalf, 1)
	fmt.Printf("%s %s %s %s %s\n", padRight(curRec.ArAcct, 4), WsAmtEd, WsWrapEd, WsSafeEd, WsHalfEd)
	READPARA()
}

func SUMMARYPARA() {
	fmt.Printf("RECORDS: %s\n", formatPic99(WsCount))
	fmt.Printf("OVERFLOWS: %s\n", formatPic99(WsOverflows))
}

func OVERFLOWPARA() {
	WsOverflows = addPic99(WsOverflows, 1)
}

func main() {
	WsEofFlag = "N"
	WsBigTotal = decimal.New(0, 0)
	WsWrapTotal = decimal.New(0, 0)
	WsSafeTotal = decimal.New(0, 0)
	WsOverflows = 0
	WsCount = 0
	WsHalf = decimal.New(0, 0)
	MAINPARA()
}
